// @vitest-environment node
import { execFileSync } from 'node:child_process'
import { resolve } from 'node:path'
import type { PGlite } from '@electric-sql/pglite'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import type { HistorySummary } from '../planner/types'
import { createSupabaseLikeDb, roles } from './supabaseTestDb'

vi.setConfig({ testTimeout: 30_000, hookTimeout: 60_000 })

// The LLE procurement sample seed (0005_planner_lle_sample.sql, generated by
// scripts/gen-lle-sample.mjs): is it coherent enough for the planner to build a schedule from?

const USER = '11111111-1111-1111-1111-111111111111'
const LLE = 'lle-procurement'

let db: PGlite

beforeAll(async () => {
  db = await createSupabaseLikeDb()
  // Read as a signed-in user, as the planning server does: RLS applies.
  await roles(db).asUser(USER)
}, 60_000)

afterAll(async () => {
  await db.close()
}, 60_000)

async function count(table: string, where = 'true', params: unknown[] = []): Promise<number> {
  const r = await db.query<{ n: number }>(`select count(*)::int as n from ${table} where ${where}`, params)
  return r.rows[0].n
}

async function summary(type: string, equipment: string | null = null): Promise<HistorySummary> {
  const r = await db.query<{ s: HistorySummary }>(`select planner_history_summary($1, $2) as s`, [type, equipment])
  return r.rows[0].s
}

describe('LLE sample seed (0005)', () => {
  type Link = { from: string; type: string; lagDays: number }
  type Row = { code: string; sequence: number; default_links: Link[]; default_days: number; is_target: boolean }

  async function catalog(): Promise<Row[]> {
    const r = await db.query<Row>(
      `select code, sequence, default_links, default_days, is_target from activity_catalog where schedule_type = $1 order by sequence`,
      [LLE],
    )
    return r.rows
  }

  it('defines the LLE procurement schedule type with exactly one zero-duration target, last in sequence', async () => {
    const t = await db.query<{ name: string }>(`select name from schedule_types where id = $1`, [LLE])
    expect(t.rows).toHaveLength(1)
    const rows = await catalog()
    expect(rows.length).toBeGreaterThanOrEqual(10)
    const targets = rows.filter((r) => r.is_target)
    expect(targets).toHaveLength(1)
    expect(targets[0].default_days).toBe(0)
    expect(targets[0]).toBe(rows[rows.length - 1])
    expect(rows.map((r) => r.sequence)).toEqual(rows.map((_, i) => i + 1))
    for (const r of rows.filter((x) => !x.is_target)) expect(r.default_days).toBeGreaterThan(0)
  })

  it('links only to catalog codes, with valid types and lags, and forms an acyclic network', async () => {
    const rows = await catalog()
    const codes = new Set(rows.map((r) => r.code))
    for (const r of rows) {
      for (const l of r.default_links) {
        expect(codes.has(l.from), `${r.code} <- ${l.from}`).toBe(true)
        expect(['FS', 'SS', 'FF', 'SF']).toContain(l.type)
        expect(Number.isInteger(l.lagDays)).toBe(true)
        expect(l.from).not.toBe(r.code)
      }
    }
    // Kahn's algorithm: every activity must be reachable in topological order.
    const preds = new Map(rows.map((r) => [r.code, new Set(r.default_links.map((l) => l.from))]))
    const done = new Set<string>()
    let progress = true
    while (progress) {
      progress = false
      for (const [code, ps] of preds) {
        if (!done.has(code) && [...ps].every((p) => done.has(p))) {
          done.add(code)
          progress = true
        }
      }
    }
    expect(done.size).toBe(rows.length)
    // Everything but the first activity has a predecessor, and only the target has no successor.
    const hasSucc = new Set(rows.flatMap((r) => r.default_links.map((l) => l.from)))
    expect(rows.filter((r) => r.default_links.length === 0).map((r) => r.sequence)).toEqual([1])
    expect(rows.filter((r) => !hasSucc.has(r.code)).every((r) => r.is_target)).toBe(true)
  })

  it('holds only sample projects, 6 to 10 per equipment type, each with activities and labelled as samples', async () => {
    const eq = await db.query<{ equipment_type: string; n: number }>(
      `select equipment_type, count(*)::int as n from history_projects where schedule_type = $1 group by 1 order by 1`,
      [LLE],
    )
    expect(eq.rows.length).toBeGreaterThanOrEqual(5)
    for (const r of eq.rows) {
      expect(r.n).toBeGreaterThanOrEqual(6)
      expect(r.n).toBeLessThanOrEqual(10)
    }
    expect(await count('history_projects', `schedule_type = $1 and (not is_sample or notes not ilike '%sample%')`, [LLE])).toBe(0)
    expect(
      await count(
        'history_projects p',
        `schedule_type = $1 and not exists (select 1 from history_activities a where a.project_id = p.id)`,
        [LLE],
      ),
    ).toBe(0)
    // History never records the zero-duration target milestone.
    expect(
      await count('history_activities a', `exists (select 1 from activity_catalog c where c.schedule_type = a.schedule_type and c.code = a.code and c.is_target)`),
    ).toBe(0)
  })

  it('summarizes as sample-only, with plausible, ordered statistics for every non-target activity', async () => {
    const all = await summary(LLE)
    expect(all.sampleOnly).toBe(true)
    const rows = await catalog()
    const work = rows.filter((r) => !r.is_target).map((r) => r.code)
    expect(all.stats.map((s) => s.code)).toEqual(work)
    for (const s of all.stats) {
      expect(s.min).toBeGreaterThan(0)
      expect(s.min).toBeLessThanOrEqual(s.p50)
      expect(s.p50).toBeLessThanOrEqual(s.p80)
      expect(s.p80).toBeLessThanOrEqual(s.max)
    }
    const eq = await db.query<{ equipment_type: string }>(`select equipment_type from planner_equipment_types where schedule_type = $1`, [LLE])
    for (const { equipment_type } of eq.rows) {
      const one = await summary(LLE, equipment_type)
      expect(one.sampleOnly).toBe(true)
      expect(one.projectCount).toBeGreaterThanOrEqual(6)
      // Some variety: manufacturing durations are not all identical.
      const mfg = one.stats.find((s) => s.code === 'MFG')!
      expect(mfg.max).toBeGreaterThan(mfg.min)
    }
  })

  it('is exactly what scripts/gen-lle-sample.mjs generates', () => {
    const root = resolve(__dirname, '../..')
    expect(() => execFileSync(process.execPath, ['scripts/gen-lle-sample.mjs', '--check'], { cwd: root, stdio: 'pipe' })).not.toThrow()
  })
})
